import math

def BaseFunction(i, u, k, U):
    if u <= 0.0:
        u = 0.0
    if u >= 1.0:
        u = 1.0
    if k == 0:
        if U[i] <= u:
            if u < U[i + 1]:
                return 1
            if 1 - U[i + 1] <= 1e-05:
                if U[i + 1] - u <= 1e-05:
                    return 1.0
            return 0
    else:
        Len1 = U[i + k] - U[i]
        Len2 = U[i + k + 1] - U[i + 1]
        if Len1 <= 1e-06:
            Len1 = 1
        if Len2 <= 1e-06:
            Len2 = 1
        a = (u - U[i]) / Len1 * BaseFunction(i, u, k - 1, U)
        b = (U[i + k + 1] - u) / Len2 * BaseFunction(i + 1, u, k - 1, U)
        return a + b


G5_BSpline_U = [0,0,0,0,1,1,1,1]
G5_BSpline_P = [0, 0] * 4
G5_BSpline_K = 3

def G5_BSpline(axis, u):
    sum = 0
    for i in range(4):
        sum += G5_BSpline_P[i][axis] * BaseFunction(i, u, G5_BSpline_K, G5_BSpline_U)

    return sum


def planG5(n):
    coords = []
    for i in range(n):
        u = 1.0 * i / (n - 1)
        x = G5_BSpline(0, u)
        y = G5_BSpline(1, u)
        coords.append([x, y])

    return coords


ARC_PLANE_X_Y = 0
ARC_PLANE_X_Z = 1
ARC_PLANE_Y_Z = 2
X_AXIS = 0
Y_AXIS = 1
Z_AXIS = 2
E_AXIS = 3

class ArcSupport:

    def __init__(self, config):
        self.printer = config.get_printer()
        self.mm_per_arc_segment = config.getfloat("resolution", 1.0, above=0.0)
        self.circular_interpolate = config.getboolean("circular_interpolate", False)
        self.gcode_move = self.printer.load_object(config, "gcode_move")
        self.gcode = self.printer.lookup_object("gcode")
        self.gcode.register_command("G2", self.cmd_G2)
        self.gcode.register_command("G3", self.cmd_G3)
        self.gcode.register_command("G17", self.cmd_G17)
        self.gcode.register_command("G18", self.cmd_G18)
        self.gcode.register_command("G19", self.cmd_G19)
        self.gcode.register_command("G5", self.cmd_G5)
        self.Coord = self.gcode.Coord
        self.plane = ARC_PLANE_X_Y

    def cmd_G2(self, gcmd):
        self._cmd_inner(gcmd, True)

    def cmd_G3(self, gcmd):
        self._cmd_inner(gcmd, False)

    def cmd_G17(self, gcmd):
        self.plane = ARC_PLANE_X_Y

    def cmd_G18(self, gcmd):
        self.plane = ARC_PLANE_X_Z

    def cmd_G19(self, gcmd):
        self.plane = ARC_PLANE_Y_Z

    def cmd_G5(self, gcmd):
        gcodestatus = self.gcode_move.get_status()
        if not gcodestatus["absolute_coordinates"]:
            raise gcmd.error("G2/G3 does not support relative move mode")
        currentPos = gcodestatus["gcode_position"]
        asTarget = self.Coord(x=(gcmd.get_float("X", currentPos[0])), y=(gcmd.get_float("Y", currentPos[1])),
          z=(gcmd.get_float("Z", currentPos[2])),
          e=None)
        asPlanar = [gcmd.get_float(a, 0.0) for i, a in enumerate("IJPQ")]
        asE = gcmd.get_float("E", None)
        asF = gcmd.get_float("F", None)
        G5_BSpline_P.clear()
        G5_BSpline_P.append([currentPos[0], currentPos[1]])
        G5_BSpline_P.append([currentPos[0] + asPlanar[0], currentPos[1] + asPlanar[1]])
        G5_BSpline_P.append([asTarget[0] + asPlanar[2], asTarget[1] + asPlanar[3]])
        G5_BSpline_P.append([asTarget[0], asTarget[1]])
        coords = planG5(100)
        e_per_move = e_base = 0.0
        if asE is not None:
            if gcodestatus["absolute_extrude"]:
                e_base = currentPos[3]
            e_per_move = (asE - e_base) / len(coords)
        for coord in coords:
            g1_params = {'X':coord[0], 
             'Y':coord[1]}
            if e_per_move:
                g1_params["E"] = e_base + e_per_move
                if gcodestatus["absolute_extrude"]:
                    e_base += e_per_move
                if asF is not None:
                    g1_params["F"] = asF
            g1_gcmd = self.gcode.create_gcode_command("G1", "G1", g1_params)
            self.gcode_move.cmd_G1(g1_gcmd)

    def _cmd_inner(self, gcmd, clockwise):
        gcodestatus = self.gcode_move.get_status()
        if not gcodestatus["absolute_coordinates"]:
            raise gcmd.error("G2/G3 does not support relative move mode")
        currentPos = gcodestatus["gcode_position"]
        asTarget = self.Coord(x=(gcmd.get_float("X", currentPos[0])), y=(gcmd.get_float("Y", currentPos[1])),
          z=(gcmd.get_float("Z", currentPos[2])),
          e=None)
        if gcmd.get_float("R", None) is not None:
            raise gcmd.error("G2/G3 does not support R moves")
        asPlanar = [gcmd.get_float(a, 0.0) for i, a in enumerate("IJ")]
        axes = (X_AXIS, Y_AXIS, Z_AXIS)
        if self.plane == ARC_PLANE_X_Z:
            asPlanar = [gcmd.get_float(a, 0.0) for i, a in enumerate("IK")]
            axes = (X_AXIS, Z_AXIS, Y_AXIS)
        elif self.plane == ARC_PLANE_Y_Z:
            asPlanar = [gcmd.get_float(a, 0.0) for i, a in enumerate("JK")]
            axes = (Y_AXIS, Z_AXIS, X_AXIS)
        if not asPlanar[0]:
            if not asPlanar[1]:
                raise gcmd.error("G2/G3 requires IJ, IK or JK parameters")
        if self.circular_interpolate:
            if self.plane == ARC_PLANE_X_Y:
                self.gcode_move.cmd_G_move(gcmd, asPlanar, clockwise, True)
                return
            asE = gcmd.get_float("E", None)
            asF = gcmd.get_float("F", None)
            coords = (self.planArc)(currentPos, asTarget, asPlanar, clockwise, *axes)
            e_per_move = e_base = 0.0
            if asE is not None:
                if gcodestatus["absolute_extrude"]:
                    e_base = currentPos[3]
                e_per_move = (asE - e_base) / len(coords)
            for coord in coords:
                g1_params = {'X':coord[0], 
                 'Y':coord[1],  'Z':coord[2]}
                if e_per_move:
                    g1_params["E"] = e_base + e_per_move
                    if gcodestatus["absolute_extrude"]:
                        e_base += e_per_move
                    if asF is not None:
                        g1_params["F"] = asF
                g1_gcmd = self.gcode.create_gcode_command("G1", "G1", g1_params)
                self.gcode_move.cmd_G1(g1_gcmd)

    def planArc(self, currentPos, targetPos, offset, clockwise, alpha_axis, beta_axis, helical_axis):
        r_P = -offset[0]
        r_Q = -offset[1]
        center_P = currentPos[alpha_axis] - r_P
        center_Q = currentPos[beta_axis] - r_Q
        rt_Alpha = targetPos[alpha_axis] - center_P
        rt_Beta = targetPos[beta_axis] - center_Q
        angular_travel = math.atan2(r_P * rt_Beta - r_Q * rt_Alpha, r_P * rt_Alpha + r_Q * rt_Beta)
        if angular_travel < 0.0:
            angular_travel += 2.0 * math.pi
        if clockwise:
            angular_travel -= 2.0 * math.pi
        if angular_travel == 0.0 and currentPos[alpha_axis] == targetPos[alpha_axis]:
            if currentPos[beta_axis] == targetPos[beta_axis]:
                angular_travel = 2.0 * math.pi
            linear_travel = targetPos[helical_axis] - currentPos[helical_axis]
            radius = math.hypot(r_P, r_Q)
            flat_mm = radius * angular_travel
            if linear_travel:
                mm_of_travel = math.hypot(flat_mm, linear_travel)
            else:
                mm_of_travel = math.fabs(flat_mm)
            segments = max(1.0, math.floor(mm_of_travel / self.mm_per_arc_segment))
            theta_per_segment = angular_travel / segments
            linear_per_segment = linear_travel / segments
            coords = []
            for i in range(1, int(segments)):
                dist_Helical = i * linear_per_segment
                cos_Ti = math.cos(i * theta_per_segment)
                sin_Ti = math.sin(i * theta_per_segment)
                r_P = -offset[0] * cos_Ti + offset[1] * sin_Ti
                r_Q = -offset[0] * sin_Ti - offset[1] * cos_Ti
                c = [
                 None, None, None, None]
                c[alpha_axis] = center_P + r_P
                c[beta_axis] = center_Q + r_Q
                c[helical_axis] = currentPos[helical_axis] + dist_Helical
                coords.append((self.Coord)(*c))

            coords.append(targetPos)
            return coords


def load_config(config):
    return ArcSupport(config)

